const email = $json;

// Extract sender email cleanly
let senderEmail = "";
if (email.from && email.from.value && email.from.value.length > 0) {
  senderEmail = email.from.value[0].address || "";
} else if (typeof email.from === 'string') {
  senderEmail = email.from;
}

// Handle body parsing (plain text and HTML emails)
let parsedBody = "";
if (email.text) {
  parsedBody = email.text.trim();
} else if (email.html) {
  // Pre-process common HTML block tags to preserve formatting and readability
  let cleanHtml = email.html
    .replace(/<style([\s\S]*?)<\/style>/gi, '')   // Remove CSS styles
    .replace(/<script([\s\S]*?)<\/script>/gi, '') // Remove JS scripts
    .replace(/<\/p>/gi, '\n\n')                  // Convert paragraphs to double newlines
    .replace(/<br\s*\/?>/gi, '\n')                 // Convert breaks to newlines
    .replace(/<\/div>/gi, '\n')                   // Convert div ends to newlines
    .replace(/<\/tr>/gi, '\n')                    // Convert table row ends to newlines
    .replace(/<\/li>/gi, '\n');                   // Convert list item ends to newlines

  // Strip all remaining HTML tags
  parsedBody = cleanHtml
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/\n\s*\n+/g, '\n\n')                // Normalize multiple newlines
    .replace(/[ \t]+/g, ' ')                      // Collapse multiple horizontal spaces
    .trim();
}

return {
  json: {
    ticketId: email.messageId || email.uid || `email-${Date.now()}`,
    source: "Email",
    sender: senderEmail,
    subject: email.subject || "[No Subject]",
    body: parsedBody,
    receivedAt: email.date || new Date().toISOString()
  }
};
